From bbebbe8e25245e0aac15d958ca68235cdc01a348 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 18:53:46 +0100
Subject: [PATCH] applets/quicklaunch: allow choosing an icon for the popup
 button

In a panel the popup button always showed an arrow, so with several
Quicklaunch widgets there was no way to tell their popups apart. Add a
"Popup icon" setting, defaulting to the arrow, like other widgets have.

BUG: 498274
---
 applets/quicklaunch/ConfigGeneral.qml | 81 +++++++++++++++++++++++++++
 applets/quicklaunch/main.qml          |  6 +-
 applets/quicklaunch/main.xml          |  3 +
 3 files changed, 88 insertions(+), 2 deletions(-)

diff --git a/applets/quicklaunch/ConfigGeneral.qml b/applets/quicklaunch/ConfigGeneral.qml
index 11b6b38a9..58e528250 100644
--- a/applets/quicklaunch/ConfigGeneral.qml
+++ b/applets/quicklaunch/ConfigGeneral.qml
@@ -10,7 +10,9 @@ import QtQuick.Controls as QQC2

 import org.kde.plasma.plasmoid
 import org.kde.plasma.core as PlasmaCore
+import org.kde.iconthemes as KIconThemes
 import org.kde.kirigami as Kirigami
+import org.kde.ksvg as KSvg
 import org.kde.kcmutils as KCM

 KCM.SimpleKCM {
@@ -21,6 +23,7 @@ KCM.SimpleKCM {
     property alias cfg_maxSectionCount: maxSectionCount.value
     property alias cfg_showLauncherNames: showLauncherNames.checked
     property alias cfg_enablePopup: enablePopup.checked
+    property string cfg_popupIcon: Plasmoid.configuration.popupIcon
     property alias cfg_title: title.text

     Kirigami.FormLayout {
@@ -49,6 +52,84 @@ KCM.SimpleKCM {
             text: i18nc("@option:check", "Enable popup")
         }

+        QQC2.Button {
+            id: iconButton
+
+            Kirigami.FormData.label: i18nc("@label prefix for icon-only button", "Popup icon:")
+
+            implicitWidth: previewFrame.width + Kirigami.Units.smallSpacing * 2
+            implicitHeight: previewFrame.height + Kirigami.Units.smallSpacing * 2
+            enabled: enablePopup.checked
+            hoverEnabled: true
+
+            Accessible.name: i18nc("@action:button", "Change popup icon")
+            Accessible.description: i18nc("@info:whatsthis", "Current icon is %1. Click to open menu to change the current icon or reset to the default icon.", root.cfg_popupIcon)
+            Accessible.role: Accessible.ButtonMenu
+
+            QQC2.ToolTip.delay: Kirigami.Units.toolTipDelay
+            QQC2.ToolTip.text: i18nc("@info:tooltip", "Icon name is \"%1\"", root.cfg_popupIcon)
+            QQC2.ToolTip.visible: iconButton.hovered && root.cfg_popupIcon.length > 0
+
+            onPressed: iconMenu.opened ? iconMenu.close() : iconMenu.open()
+
+            KIconThemes.IconDialog {
+                id: iconDialog
+                onIconNameChanged: {
+                    root.cfg_popupIcon = iconName || "";
+                }
+            }
+
+            KSvg.FrameSvgItem {
+                id: previewFrame
+                anchors.centerIn: parent
+                imagePath: Plasmoid.formFactor === PlasmaCore.Types.Vertical || Plasmoid.formFactor === PlasmaCore.Types.Horizontal
+                        ? "widgets/panel-background" : "widgets/background"
+                width: Kirigami.Units.iconSizes.large + fixedMargins.left + fixedMargins.right
+                height: Kirigami.Units.iconSizes.large + fixedMargins.top + fixedMargins.bottom
+
+                Kirigami.Icon {
+                    anchors.centerIn: parent
+                    width: Kirigami.Units.iconSizes.large
+                    height: width
+                    source: {
+                        if (root.cfg_popupIcon) {
+                            return root.cfg_popupIcon;
+                        } else if (Plasmoid.location == PlasmaCore.Types.TopEdge) {
+                            return "arrow-down";
+                        } else if (Plasmoid.location == PlasmaCore.Types.LeftEdge) {
+                            return "arrow-right";
+                        } else if (Plasmoid.location == PlasmaCore.Types.RightEdge) {
+                            return "arrow-left";
+                        } else if (root.vertical) {
+                            return "arrow-right";
+                        } else {
+                            return "arrow-up";
+                        }
+                    }
+                }
+            }
+
+            QQC2.Menu {
+                id: iconMenu
+
+                // Appear below the button
+                y: +parent.height
+
+                QQC2.MenuItem {
+                    text: i18nc("@item:inmenu Open icon chooser dialog", "Choose…")
+                    icon.name: "document-open-folder"
+                    Accessible.description: i18nc("@info:whatsthis", "Choose an icon for the popup")
+                    onClicked: iconDialog.open()
+                }
+                QQC2.MenuItem {
+                    text: i18nc("@item:inmenu Reset icon to default", "Reset to default icon")
+                    icon.name: "edit-clear"
+                    enabled: root.cfg_popupIcon !== ""
+                    onClicked: root.cfg_popupIcon = ""
+                }
+            }
+        }
+

         Item {
             Kirigami.FormData.isSection: true
diff --git a/applets/quicklaunch/main.qml b/applets/quicklaunch/main.qml
index 012b52556..efa646bd4 100644
--- a/applets/quicklaunch/main.qml
+++ b/applets/quicklaunch/main.qml
@@ -170,7 +170,7 @@ PlasmoidItem {
                 Kirigami.Icon {
                     anchors.fill: parent

-                    rotation: popup.visible ? 180 : 0
+                    rotation: popup.visible && !Plasmoid.configuration.popupIcon ? 180 : 0
                     Behavior on rotation {
                         RotationAnimation {
                             duration: Kirigami.Units.shortDuration * 3
@@ -178,7 +178,9 @@ PlasmoidItem {
                     }

                     source: {
-                        if (Plasmoid.location == PlasmaCore.Types.TopEdge) {
+                        if (Plasmoid.configuration.popupIcon) {
+                            return Plasmoid.configuration.popupIcon;
+                        } else if (Plasmoid.location == PlasmaCore.Types.TopEdge) {
                             return "arrow-down";
                         } else if (Plasmoid.location == PlasmaCore.Types.LeftEdge) {
                             return "arrow-right";
diff --git a/applets/quicklaunch/main.xml b/applets/quicklaunch/main.xml
index 71528c90e..4ffdde4a8 100644
--- a/applets/quicklaunch/main.xml
+++ b/applets/quicklaunch/main.xml
@@ -15,6 +15,9 @@
     <entry name="enablePopup" type="Bool">
       <default>false</default>
     </entry>
+    <entry name="popupIcon" type="String">
+      <default></default>
+    </entry>
     <entry name="title" type="String">
       <default></default>
     </entry>
-- 
2.53.0
